import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

export default function Login() {
  const { login, user } = useAuth();
  const navigate = useNavigate();

  const handleLoginMember = () => {
    login('member');
    navigate('/');
  };

  const handleLoginAdmin = () => {
    login('admin');
    navigate('/admin');
  };

  return (
    <div style={{
      maxWidth: '500px',
      margin: '80px auto',
      padding: '40px',
      background: '#120731',
      borderRadius: '12px',
      textAlign: 'center',
      boxShadow: '0 8px 24px rgba(0,0,0,0.3)',
      border: '1px solid rgba(255,255,255,0.1)'
    }}>
      <h2 style={{ color: '#FFC85C', marginTop: 0 }}>🔑 เข้าสู่ระบบ / จำลองสิทธิ์</h2>
      <p style={{ color: '#CCC', marginBottom: '30px' }}>
        สถานะปัจจุบัน: <strong style={{ color: '#FFF' }}>{user.name} ({user.role})</strong>
      </p>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <button
          onClick={handleLoginMember}
          style={{
            padding: '14px',
            background: '#FFC85C',
            color: '#1E104E',
            border: 'none',
            borderRadius: '8px',
            fontWeight: 'bold',
            fontSize: '16px',
            cursor: 'pointer'
          }}
        >
          🎓 จำลองเข้าสู่ระบบเป็น Member (นักศึกษา)
        </button>

        <button
          onClick={handleLoginAdmin}
          style={{
            padding: '14px',
            background: '#FF653F',
            color: '#FFF',
            border: 'none',
            borderRadius: '8px',
            fontWeight: 'bold',
            fontSize: '16px',
            cursor: 'pointer'
          }}
        >
          🛡️ จำลองเข้าสู่ระบบเป็น Admin (ผู้ดูแลระบบ)
        </button>
      </div>
    </div>
  );
}
